CREATE OR ALTER PROCEDURE [dbo].[uspDocumentFile_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @TestDemoId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[TestDemoId]
			, t.[FileName]
			, t.[FileSize]
			, t.[FileType]
			, t.[FileNameHas]
			, t.[CreatedDate]
		FROM [dbo].[DocumentFile] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[FileName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@TestDemoId IS NULL OR t.[TestDemoId] = @TestDemoId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'testDemoId' THEN r.[TestDemoId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'testDemoId' THEN r.[TestDemoId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fileName' THEN r.[FileName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fileName' THEN r.[FileName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fileSize' THEN r.[FileSize] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fileSize' THEN r.[FileSize] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fileType' THEN r.[FileType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fileType' THEN r.[FileType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fileNameHas' THEN r.[FileNameHas] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fileNameHas' THEN r.[FileNameHas] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
